insert into public.livro_habilidades(ref, sistema, fonte, classe, grupo, trilha, nex, ordem, nome, circulo, elemento, dados) values
('op:origem:sah:Amigo dos Animais','op','sah',null,'origem',null,null,5000,'Companheiro Animal',null,null,'{"tipo": "origem", "pe": 0, "origem": "Amigo dos Animais", "pericias": ["Adestramento", "Percepção"], "desc": "Entende intenções e sentimentos de animais e pode usar Adestramento para mudar a atitude deles. Tem um animal de estimação que é um aliado: +2 em uma perícia à sua escolha (aprovada pelo mestre). Em NEX 35% ele também dá o bônus de um tipo de aliado à sua escolha; em NEX 70%, também a habilidade desse tipo de aliado. Se ele morrer: perde 10 de Sanidade permanente e fica perturbado até o fim da cena. Arranjar outro fica a critério do mestre (normalmente entre missões).", "ef": [], "comp": "sah", "pag": 7}'::jsonb),
('op:origem:sah:Astronauta','op','sah',null,'origem',null,null,5001,'Acostumado ao Extremo',null,null,'{"tipo": "origem", "pe": 0, "origem": "Astronauta", "pericias": ["Ciências", "Fortitude"], "desc": "Ao sofrer dano de fogo, frio ou mental, gaste 1 PE para reduzir esse dano em 5. Cada uso seguinte na mesma cena custa +1 PE.", "ef": [], "comp": "sah", "pag": 8}'::jsonb),
('op:origem:sah:Chef do Outro Lado','op','sah',null,'origem',null,null,5002,'Fome do Outro Lado',null,null,'{"tipo": "origem", "pe": 0, "origem": "Chef do Outro Lado", "pericias": ["Ocultismo", "Profissão"], "desc": "Profissão treinada: cozinheiro. Usa partes de criaturas do Outro Lado como ingredientes (item categoria I, 0,5 espaço; pede no início da missão ou tira de criatura derrotada Pequena ou maior: 1 ingrediente). Ação de interlúdio + 1 ingrediente: prato especial com Profissão (cozinheiro) DT 15 + 1d20 (o mestre esconde o resultado até alguém comer). Passou: RD 10 contra o tipo de dano do elemento da criatura; falhou: vulnerabilidade a esse dano. Dura até o fim da próxima cena. Cada refeição custa 1 de Sanidade permanente. Com a regra opcional de NEX e experiência (SaH p.98), cada parte de criatura diferente ingerida dá +3% de NEX. A Ordem não apoia.", "ef": [], "comp": "sah", "pag": 8}'::jsonb),
('op:origem:sah:Colegial','op','sah',null,'origem',null,null,5003,'Poder da Amizade',null,null,'{"tipo": "origem", "pe": 0, "origem": "Colegial", "pericias": ["Atualidades", "Tecnologia"], "desc": "Escolha um personagem como melhor amigo. Em alcance médio dele, podendo ao menos trocar olhares, você recebe +2 em todos os testes de perícia. Se ele morrer, seu total de PE cai 1 a cada 5% de NEX até o fim da missão; no início da próxima missão pode escolher outro melhor amigo.", "ef": [], "comp": "sah", "pag": 9}'::jsonb),
('op:origem:sah:Cosplayer','op','sah',null,'origem',null,null,5004,'Não É Fantasia, É Cosplay!',null,null,'{"tipo": "origem", "pe": 0, "origem": "Cosplayer", "pericias": ["Artes", "Vontade"], "desc": "Faz testes de disfarce com Artes no lugar de Enganação. Vestindo um cosplay ligado ao teste, recebe +2 nele (ex.: fantasia de gato dá +2 para ser furtivo e se equilibrar).", "ef": [], "comp": "sah", "pag": 9}'::jsonb),
('op:origem:sah:Diplomata','op','sah',null,'origem',null,null,5005,'Conexões',null,null,'{"tipo": "origem", "pe": 0, "origem": "Diplomata", "pericias": ["Atualidades", "Diplomacia"], "desc": "+2 em Diplomacia. Se puder contatar um NPC capaz de ajudar, gaste 10 minutos e 2 PE para trocar um teste de perícia ligado ao conhecimento desse NPC (feito até o fim da cena) por um teste de Diplomacia.", "ef": [{"a": "per:Diplomacia", "v": 2}], "comp": "sah", "pag": 9}'::jsonb),
('op:origem:sah:Explorador','op','sah',null,'origem',null,null,5006,'Manual do Sobrevivente',null,null,'{"tipo": "origem", "pe": 0, "origem": "Explorador", "pericias": ["Fortitude", "Sobrevivência"], "desc": "Ao testar para resistir a armadilhas, clima, doenças, fome, sede, fumaça, sono, sufocamento ou veneno (inclusive paranormais), gaste 2 PE para +5 no teste. Em interlúdios, sono precário conta como normal.", "ef": [], "comp": "sah", "pag": 9}'::jsonb),
('op:origem:sah:Experimento','op','sah',null,'origem',null,null,5007,'Mutação',null,null,'{"tipo": "origem", "pe": 0, "origem": "Experimento", "pericias": ["Atletismo", "Fortitude"], "desc": "Resistência a dano 2 e +2 em uma perícia originalmente de Força, Agilidade ou Vigor à sua escolha. Porém sofre –1d20 em Diplomacia.", "ef": [], "comp": "sah", "pag": 9}'::jsonb),
('op:origem:sah:Fanático por Criaturas','op','sah',null,'origem',null,null,5008,'Conhecimento Oculto',null,null,'{"tipo": "origem", "pe": 0, "origem": "Fanático por Criaturas", "pericias": ["Investigação", "Ocultismo"], "desc": "Pode usar Ocultismo para identificar criatura a partir de imagem, rastros ou indícios (descobre as características, não a identidade nem o tipo). Ao passar num teste de Ocultismo para identificar criatura, recebe +2 em todos os testes contra ela até o fim da missão.", "ef": [], "comp": "sah", "pag": 10}'::jsonb),
('op:origem:sah:Fotógrafo','op','sah',null,'origem',null,null,5009,'Através da Lente',null,null,'{"tipo": "origem", "pe": 0, "origem": "Fotógrafo", "pericias": ["Artes", "Percepção"], "desc": "Em teste de Investigação ou Percepção olhando por uma câmera ou analisando fotos, gaste 2 PE para +5. Andar olhando pela lente reduz o deslocamento à metade.", "ef": [], "comp": "sah", "pag": 10}'::jsonb),
('op:origem:sah:Inventor Paranormal','op','sah',null,'origem',null,null,5010,'Invenção Paranormal',null,null,'{"tipo": "origem", "pe": 0, "origem": "Inventor Paranormal", "pericias": ["Profissão", "Vontade"], "desc": "Profissão treinada: engenheiro. Escolha um ritual de 1º círculo: você tem um invento (categoria 0, 1 espaço) que reproduz a forma básica dele sem gastar PE. Ativar: ação padrão (ou a do ritual, a maior) + Profissão (engenheiro) DT 15, +5 a cada ativação na missão. Falhou: enguiça. Ação de interlúdio de manutenção conserta e volta a DT a 15. Pode trocar o ritual no início de cada missão.", "ef": [], "comp": "sah", "pag": 10}'::jsonb),
('op:origem:sah:Jovem Místico','op','sah',null,'origem',null,null,5011,'A Culpa é das Estrelas',null,null,'{"tipo": "origem", "pe": 0, "origem": "Jovem Místico", "pericias": ["Ocultismo", "Religião"], "desc": "Escolha um número da sorte de 1 a 6. No início de cada cena, gaste 1 PE e role 1d6: tirou um número da sorte, +2 em testes de perícia até o fim da cena; senão, acrescente mais um número da sorte para a próxima vez. Ao acertar, volta a ter um número só.", "ef": [], "comp": "sah", "pag": 11}'::jsonb),
('op:origem:sah:Legista do Turno da Noite','op','sah',null,'origem',null,null,5012,'Luto Habitual',null,null,'{"tipo": "origem", "pe": 0, "origem": "Legista do Turno da Noite", "pericias": ["Ciências", "Medicina"], "desc": "Sofre metade do dano mental de cenas ligadas à rotina de legista (morte, cadáveres, órgãos), a critério do mestre. Em Medicina para primeiros socorros ou necropsia, gaste 2 PE para +5.", "ef": [], "comp": "sah", "pag": 11}'::jsonb),
('op:origem:sah:Mateiro','op','sah',null,'origem',null,null,5013,'Mapa Celeste',null,null,'{"tipo": "origem", "pe": 0, "origem": "Mateiro", "pericias": ["Percepção", "Sobrevivência"], "desc": "Vendo o céu, sempre sabe os pontos cardeais e chega sem se perder a lugares que já visitou. Em Sobrevivência, gaste 2 PE para rolar de novo e ficar com o melhor. Em interlúdios, sono precário conta como normal.", "ef": [], "comp": "sah", "pag": 12}'::jsonb),
