('op:origem:sah:Motorista','op','sah',null,'origem',null,null,5015,'Mãos no Volante',null,null,'{"tipo": "origem", "pe": 0, "origem": "Motorista", "pericias": ["Pilotagem", "Reflexos"], "desc": "Não sofre penalidade em ataques por estar em veículo em movimento. Pilotando, em teste de Pilotagem ou de resistência, gaste 2 PE para +5.", "ef": [], "comp": "sah", "pag": 13}'::jsonb),
('op:origem:sah:Nerd Entusiasta','op','sah',null,'origem',null,null,5016,'O Inteligentão',null,null,'{"tipo": "origem", "pe": 0, "origem": "Nerd Entusiasta", "pericias": ["Ciências", "Tecnologia"], "desc": "O bônus da ação de interlúdio ler sobe +1 dado (de +1d6 para +2d6).", "ef": [], "comp": "sah", "pag": 13}'::jsonb),
('op:origem:sah:Profetizado','op','sah',null,'origem',null,null,5017,'Luta ou Fuga',null,null,'{"tipo": "origem", "pe": 0, "origem": "Profetizado", "pericias": ["Vontade"], "desc": "Perícias: Vontade e mais uma à escolha ligada à premonição. Você sabe como vai morrer (o mestre define a cena em segredo ou junto com você). +2 em Vontade. Quando surge uma referência à premonição, recebe +2 PE temporários até o fim da cena (respeite o texto: não force gatilhos de propósito).", "ef": [{"a": "per:Vontade", "v": 2}], "comp": "sah", "pag": 13}'::jsonb),
('op:origem:sah:Psicólogo','op','sah',null,'origem',null,null,5018,'Terapia',null,null,'{"tipo": "origem", "pe": 0, "origem": "Psicólogo", "pericias": ["Intuição", "Profissão"], "desc": "Profissão treinada: psicólogo. Usa Profissão (psicólogo) como Diplomacia. Uma vez por rodada, quando você ou aliado em alcance curto falha em resistência contra efeito que causa dano mental, gaste 2 PE para fazer Profissão (psicólogo) e usar esse resultado no lugar.", "ef": [], "comp": "sah", "pag": 13}'::jsonb),
