('op:geral:poder:Foco em Perícia','op','sah','geral','poder',null,null,5028,'Foco em Perícia',null,null,'{"tipo": "poder", "desc": "Escolha uma perícia (menos Luta e Pontaria): seus testes dela rolam +1d20. Pode escolher outras vezes para perícias diferentes. Pré-requisito: treinado na perícia escolhida.", "pe": 0, "ef": [], "geral": 1, "comp": "sah", "pag": 33}'::jsonb),
