('op:geral:poder:Parceiro','op','sah','geral','poder',null,null,5036,'Parceiro',null,null,'{"tipo": "poder", "desc": "Você tem um parceiro (crie nome, aparência, personalidade): um aliado de um tipo à sua escolha (OPRPG p.171). Obedece e se arrisca por você, mas pode ir embora se maltratado. Se o perder, gaste uma folga da Ordem (SaH p.94) para ter outro. Pré-requisito: treinado em Diplomacia, NEX 30%.", "pe": 0, "ef": [], "geral": 1, "comp": "sah", "pag": 35}'::jsonb),
