(119,'Religioso','Outro','40',160,'sah','{"tamanho": "Médio", "pv": 32, "desloc": 9, "atr": {"agi": 1, "for": 1, "int": 2, "pre": 3, "vig": 1}, "fort": 0, "refl": 0, "vont": 5, "ini": 5, "perc": 5, "pericias": [{"n": "Diplomacia", "b": 5}, {"n": "Intuição", "b": 5}, {"n": "Religião", "b": 5}], "resist": "", "vuln": "", "sentidos": "", "ataques": [{"n": "Pancada", "alc": "Corpo a corpo", "teste": 5, "dano": "1d3+1 impacto"}], "habilidades": [{"n": "Fé Inabalável", "acao": "Passiva", "desc": "+10 em Vontade contra efeitos paranormais (inclusive rituais)."}, {"n": "Potência da Voz", "acao": "Passiva", "desc": "Com microfone ou amplificador, o alcance das habilidades sobe um passo e a DT +5."}, {"n": "Seguidores", "acao": "Passiva", "desc": "Sempre com 1d4+1 devotos (ficha de iniciado, OPRPG p.286)."}, {"n": "Voz Guia", "acao": "Padrão", "desc": "Pessoa em alcance curto que o ouve recebe bônus no próximo teste de perícia até o fim da próxima rodada."}, {"n": "Voz Acusadora", "acao": "Padrão", "desc": "Pessoa em alcance curto: 3d6 de dano mental e alquebrada (Vontade DT 15 metade e evita a condição)."}, {"n": "Sacrifício Sagrado", "acao": "Reação", "desc": "Uma vez por rodada, ao sofrer dano, troca de lugar com seguidor adjacente, que sofre o dano."}], "desc": "", "comp": "sah", "pag": 160, "def": 15}'::jsonb),
(120,'Predador Sofisticado','Outro','60',161,'sah','{"tamanho": "Médio", "pv": 60, "desloc": 9, "atr": {"agi": 3, "for": 3, "int": 2, "pre": 3, "vig": 1}, "fort": 5, "refl": 10, "vont": 10, "ini": 5, "perc": 10, "pericias": [{"n": "Diplomacia", "b": 10}, {"n": "Enganação", "b": 10}, {"n": "Intimidação", "b": 10}], "resist": "", "vuln": "", "sentidos": "", "ataques": [{"n": "Navalha", "alc": "Corpo a corpo, x2, crítico 19/x3", "teste": 10, "dano": "1d8+13 corte"}, {"n": "Machado", "alc": "Corpo a corpo, x2, crítico x3", "teste": 10, "dano": "2d8+13 corte"}, {"n": "Pistola Silenciada", "alc": "À distância, Curto, x2, crítico x3", "teste": 10, "dano": "1d12+13 balístico"}], "habilidades": [{"n": "Escondido em Plena Vista", "acao": "Passiva", "desc": "Em lugares movimentados, usa Enganação no lugar de Furtividade e não sofre penalidades por ações chamativas furtivo."}, {"n": "Recursos Abundantes", "acao": "Passiva", "desc": "Entra em lugares e documentos restritos e escapa de crimes menores; para os graves arranja bode expiatório (a critério do mestre)."}, {"n": "Sorriso Sedutor", "acao": "Passiva", "desc": "Quem não sabe que ele é assassino fica desprevenido contra ele e sofre –1 dado em testes contra ele."}, {"n": "Ataque Furtivo", "acao": "Livre", "desc": "Uma vez por rodada, +3d6 contra desprevenidos ou flanqueados (corpo a corpo ou alcance curto)."}, {"n": "Guarda-costas", "acao": "Padrão", "desc": "Uma vez por cena chama 1d4+1 capangas (OPRPG p.284), que entram na próxima rodada."}], "desc": "Serial killer.", "comp": "sah", "pag": 161, "def": 21}'::jsonb),
(121,'Caçador de Gente','Outro','80',162,'sah','{"tamanho": "Médio", "pv": 80, "desloc": 9, "atr": {"agi": 2, "for": 3, "int": 1, "pre": 1, "vig": 3}, "fort": 10, "refl": 10, "vont": 5, "ini": 10, "perc": 5, "pericias": [{"n": "Atletismo", "b": 10}, {"n": "Sobrevivência", "b": 10}], "resist": "", "vuln": "", "sentidos": "", "ataques": [{"n": "Pancada", "alc": "Corpo a corpo, x2", "teste": 15, "dano": "1d4+15 impacto"}, {"n": "Machado", "alc": "Corpo a corpo, x2, crítico x3", "teste": 15, "dano": "2d8+15 corte"}, {"n": "Motosserra", "alc": "Corpo a corpo, x2, crítico x4", "teste": 15, "dano": "3d6+15 corte"}], "habilidades": [{"n": "Abrutalhado", "acao": "Passiva", "desc": "Usa itens de duas mãos com uma e itens de criaturas Grandes sem penalidade. Machucado, RD 10/paranormal."}, {"n": "Área de Caça", "acao": "Passiva", "desc": "Na área isolada onde caça, +1d20 em testes de perícia."}, {"n": "Faro para Humanos", "acao": "Passiva", "desc": "+2d20 em Sobrevivência envolvendo pessoas e sente humanos pelo cheiro (faro)."}, {"n": "Ataque Furtivo", "acao": "Livre", "desc": "Uma vez por rodada, +4d6 contra desprevenidos ou flanqueados."}, {"n": "Imparável", "acao": "Movimento", "desc": "Anula efeitos que reduzem seu deslocamento (outras consequências continuam)."}, {"n": "Assustar", "acao": "Padrão", "desc": "Quem o vê ou ouve em alcance curto: 4d6 de dano mental (Vontade DT 20 metade)."}, {"n": "Fatalidade", "acao": "Padrão", "desc": "Um ataque de pancada: se acertar, além do dano causa ferimento debilitante (SaH p.105). Uma vez por cena por ser."}], "desc": "Serial killer.", "comp": "sah", "pag": 162, "def": 23}'::jsonb),
(122,'Artista da Morte','Outro','140',162,'sah','{"tamanho": "Médio", "pv": 150, "desloc": 9, "atr": {"agi": 3, "for": 1, "int": 3, "pre": 3, "vig": 1}, "fort": 5, "refl": 15, "vont": 15, "ini": 15, "perc": 15, "pericias": [{"n": "Artes", "b": 15}, {"n": "Enganação", "b": 15}, {"n": "Furtividade", "b": 15}], "resist": "", "vuln": "", "sentidos": "", "ataques": [{"n": "Bisturi", "alc": "Corpo a corpo, x2, crítico 19/x4", "teste": 15, "dano": "1d4+17 corte"}], "habilidades": [{"n": "Matar é uma Arte", "acao": "Passiva", "desc": "Usa Artes no lugar de qualquer perícia envolvendo mentes e corpos humanos (necropsia, persuadir). Com horas numa cena de crime, troca Investigação por Artes com +1d20."}, {"n": "Cenas Imprevisíveis", "acao": "Passiva", "desc": "Se quis disfarçar a morte, testes por pistas na cena têm DT +5. Se quis deixar marca, quem vê fica enjoado e, sem sair, sofre 4d8 de dano mental (Vontade DT 25 metade e evita a condição)."}, {"n": "Ataque Furtivo", "acao": "Livre", "desc": "Uma vez por rodada, +7d6 contra desprevenidos ou flanqueados."}, {"n": "Discurso Artístico", "acao": "Padrão", "desc": "Quem o ouve em alcance curto: 4d8 de dano mental, alquebrado e frustrado (Vontade DT 25 metade e evita frustrado). Uma vez por cena por pessoa."}], "desc": "Serial killer.", "comp": "sah", "pag": 162, "def": 27}'::jsonb),
(123,'Ariranha','Outro','20',163,'sah','{"tamanho": "Médio", "pv": 32, "desloc": 12, "atr": {"agi": 2, "for": 1, "int": 0, "pre": 1, "vig": 2}, "fort": 0, "refl": 5, "vont": 0, "ini": 5, "perc": 5, "pericias": [], "resist": "", "vuln": "", "sentidos": "Faro, visão na penumbra; natação 9m", "ataques": [{"n": "Mordida", "alc": "Corpo a corpo", "teste": 5, "dano": "2d4+2 corte"}], "habilidades": [{"n": "Evasão", "acao": "Passiva", "desc": "Passando em Reflexos que reduziria o dano à metade, não sofre dano."}, {"n": "Táticas Familiares", "acao": "Passiva", "desc": "+2 no ataque e dano para cada outra ariranha atacando o mesmo alvo na rodada."}], "desc": "", "comp": "sah", "pag": 163, "def": 16}'::jsonb),
(124,'Cavalo','Outro','10',163,'sah','{"tamanho": "Grande", "pv": 12, "desloc": 15, "atr": {"agi": 1, "for": 3, "int": 0, "pre": 1, "vig": 2}, "fort": 0, "refl": 5, "vont": 0, "ini": 5, "perc": 5, "pericias": [], "resist": "", "vuln": "", "sentidos": "Faro, visão na penumbra", "ataques": [{"n": "Cascos", "alc": "Corpo a corpo", "teste": 5, "dano": "2d4+3 impacto"}], "habilidades": [{"n": "Montaria", "acao": "Passiva", "desc": "Treinado em Adestramento usa como montaria: aliado que deixa o deslocamento em 15m e dá uma ação extra por rodada só para se deslocar."}], "desc": "", "comp": "sah", "pag": 163, "def": 13}'::jsonb),
(125,'Enxame de Tocandiras','Outro','20',164,'sah','{"tamanho": "Médio", "pv": 22, "desloc": 6, "atr": {"agi": 1, "for": 0, "int": 0, "pre": 1, "vig": 0}, "fort": 0, "refl": 5, "vont": 0, "ini": 5, "perc": 5, "pericias": [], "resist": "", "vuln": "", "sentidos": "Visão na penumbra; escalada 6m", "ataques": [], "habilidades": [{"n": "Enxame", "acao": "Passiva", "desc": "Entra no espaço de outros; no fim do turno causa 4d4 de perfuração a quem estiver no espaço. Imune a manobras e efeitos de alvo único sem dano; metade do dano de armas, +50% de efeitos em área."}, {"n": "Dor Debilitante", "acao": "Passiva", "desc": "Quem sofre dano dele fica com –1d20 em todos os testes (Fortitude DT 20 evita) até uma ação de dormir ou um antídoto."}, {"n": "Por Dentro das Roupas", "acao": "Passiva", "desc": "Quem sai do espaço continua sofrendo 2d4 até gastar uma ação de movimento para se livrar das formigas."}], "desc": "Fortitude –2O.", "comp": "sah", "pag": 164, "def": 16}'::jsonb),
(126,'Gorila','Outro','40',164,'sah','{"tamanho": "Grande", "pv": 70, "desloc": 9, "atr": {"agi": 2, "for": 3, "int": 0, "pre": 1, "vig": 3}, "fort": 5, "refl": 5, "vont": 0, "ini": 5, "perc": 5, "pericias": [{"n": "Atletismo", "b": 5}], "resist": "", "vuln": "", "sentidos": "Faro, visão na penumbra; escalada 9m", "ataques": [{"n": "Pancada", "alc": "Corpo a corpo, x2", "teste": 10, "dano": "1d6+3 impacto"}], "habilidades": [{"n": "Morder", "acao": "Livre", "desc": "Acertando as duas pancadas no mesmo ser, ataca com mordida (+10, 1d6+4 corte)."}], "desc": "", "comp": "sah", "pag": 164, "def": 19}'::jsonb),
(127,'Leão','Outro','60',164,'sah','{"tamanho": "Grande", "pv": 80, "desloc": 15, "atr": {"agi": 3, "for": 3, "int": 0, "pre": 2, "vig": 2}, "fort": 5, "refl": 10, "vont": 5, "ini": 10, "perc": 10, "pericias": [{"n": "Atletismo", "b": 10}, {"n": "Furtividade", "b": 8}], "resist": "", "vuln": "", "sentidos": "Faro, visão na penumbra", "ataques": [{"n": "Garras", "alc": "Corpo a corpo, x2, crítico 19", "teste": 10, "dano": "1d6+4 corte"}, {"n": "Mordida", "alc": "Corpo a corpo", "teste": 10, "dano": "1d8+4 corte"}], "habilidades": [{"n": "Agarrão", "acao": "Livre", "desc": "Acertando mordida em ser Médio ou menor, pode agarrar (teste +12)."}, {"n": "Bote", "acao": "Completa", "desc": "Investida com mordida e as duas garras no mesmo alvo, todos com o bônus."}], "desc": "", "comp": "sah", "pag": 164, "def": 18}'::jsonb),
(128,'Lobo','Outro','20',165,'sah','{"tamanho": "Médio", "pv": 18, "desloc": 12, "atr": {"agi": 3, "for": 3, "int": 0, "pre": 1, "vig": 2}, "fort": 5, "refl": 5, "vont": 0, "ini": 5, "perc": 5, "pericias": [{"n": "Sobrevivência", "b": 10}], "resist": "", "vuln": "", "sentidos": "Faro, visão na penumbra", "ataques": [{"n": "Mordida", "alc": "Corpo a corpo", "teste": 5, "dano": "1d6+4 corte"}], "habilidades": [{"n": "Táticas de Alcateia", "acao": "Passiva", "desc": "Flanqueando, +1d20 extra no ataque e +1d6 de dano na mordida."}, {"n": "Derrubar", "acao": "Livre", "desc": "Acertando a mordida, pode derrubar (teste +5)."}], "desc": "", "comp": "sah", "pag": 165, "def": 15}'::jsonb),
(129,'Touro','Outro','20',165,'sah','{"tamanho": "Grande", "pv": 38, "desloc": 12, "atr": {"agi": 1, "for": 3, "int": 0, "pre": 1, "vig": 2}, "fort": 5, "refl": 0, "vont": 0, "ini": 0, "perc": 5, "pericias": [], "resist": "", "vuln": "", "sentidos": "Faro, visão na penumbra", "ataques": [{"n": "Chifres", "alc": "Corpo a corpo", "teste": 5, "dano": "2d6+6 perfuração"}], "habilidades": [{"n": "Atropelamento", "acao": "Completa", "desc": "Até o dobro do deslocamento em linha reta passando por seres menores: 2d6+6 de impacto e caídos (Reflexos DT 15 metade e evita). Recarga: movimento."}], "desc": "", "comp": "sah", "pag": 165, "def": 15}'::jsonb),
(130,'Urso Pardo','Outro','60',165,'sah','{"tamanho": "Grande", "pv": 90, "desloc": 12, "atr": {"agi": 1, "for": 3, "int": 0, "pre": 2, "vig": 3}, "fort": 10, "refl": 5, "vont": 0, "ini": 5, "perc": 5, "pericias": [{"n": "Atletismo", "b": 10}], "resist": "Balístico, corte, impacto e perfuração 2", "vuln": "", "sentidos": "Faro, visão na penumbra", "ataques": [{"n": "Garras", "alc": "Corpo a corpo, x2, crítico 19", "teste": 10, "dano": "1d6+4 corte"}, {"n": "Mordida", "alc": "Corpo a corpo", "teste": 10, "dano": "1d8+4 corte"}], "habilidades": [{"n": "Agarrão", "acao": "Livre", "desc": "Acertando mordida em ser Médio ou menor, pode agarrar (teste +12)."}], "desc": "", "comp": "sah", "pag": 165, "def": 19}'::jsonb)
insert into public.livro_regras(ref, sistema, fonte, grupo, subgrupo, nome, ordem, pagina, texto, dados) values
('op:sah:jogo:Rodadas e turnos','op','sah','jogo','Investigação','Rodadas e turnos',6000,81,'Algumas cenas se dividem em rodadas e turnos; o mestre decide quanto tempo dura uma rodada (1 minuto numa busca frenética, 1 hora numa calma). Todos agem e a rodada recomeça na mesma ordem.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Atributos negativos','op','sah','jogo','Investigação','Atributos negativos',6001,81,'Atributo abaixo de 0 testa como 0, mas joga 1d20 extra por ponto negativo e fica com o menor (atributo –2: rola 4d20, usa o pior).','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Busca obstinada','op','sah','jogo','Investigação','Busca obstinada',6002,81,'Como procurar pistas, com +1d20 no teste, mas perde 1d4 de Sanidade por vez que já fez essa ação na cena (1d4, depois 2d4...).','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Recapitular','op','sah','jogo','Investigação','Recapitular',6003,81,'O jogador recapitula em voz alta, interpretando, o que o grupo já sabe. Se o mestre achar coerente: Intelecto DT 15; passou, nova pista. Depois de um sucesso, ninguém mais usa na cena.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Compartilhar','op','sah','jogo','Investigação','Compartilhar',6004,81,'Explica uma pista a outro jogador, interpretando; o outro faz Intelecto DT 15 como ação livre e, se passar, o mestre destaca o que importa nela. Uma vez com sucesso por cena.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Eventos de investigação (2d6)','op','sah','jogo','Investigação','Eventos de investigação (2d6)',6005,82,'No início de cada rodada o mestre pode escolher ou rolar 2d6 (cada evento uma vez por cena; repetido = sem evento). 2 Indício traumático: Presença DT 15 ou perde uma ação do próximo interlúdio. 3 Atenção inesperada: alguém gasta a ação ou a urgência cai 1 rodada. 4 Lembrança opressiva: até o fim da cena, quem falhar numa ação de investigação perde 1 PE. 5 Momento de tensão: 1d4 de dano mental de medo (Vontade DT 15 evita). 6-8 Sem evento. 9 Distração: um personagem aleatório sofre –1d20 na rodada. 10 Ferimento: um personagem aleatório sofre –2 nos testes de um atributo (1d10: 1-2 Agi, 3-4 For, 5-6 Int, 7-8 Pre, 9-10 Vig) até Medicina DT 20 ou uma ação de dormir. 11 Complicação: todos sofrem –1d20 até alguém gastar a ação e passar numa perícia apropriada DT 20. 12 Auxílio inesperado: todos +2 na rodada.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Urgência','op','sah','jogo','Investigação','Urgência',6006,83,'Toda investigação tem rodadas de urgência; defina antes o que a encerra (polícia chegando, navio partindo, criatura surgindo, ou só o cansaço). Pode avisar ou não os jogadores (Percepção para notar). Continuar depois do fim é possível, mas cada rodada extra aumenta o risco (ex.: visibilidade sobe sozinha).','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Sucesso a qualquer custo','op','sah','jogo','Investigação','Sucesso a qualquer custo',6007,84,'Se o grupo termina a cena sem achar uma pista crucial, pode declarar que a obtém a qualquer custo: um personagem acha, mas seu total de PE cai em valor igual ao limite de PE até o fim da missão. Normalmente uma vez por missão.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Investigações livres','op','sah','jogo','Investigação','Investigações livres',6008,86,'Fora de momentos de urgência real, narre a investigação de forma fluida (sem rodadas): os jogadores descrevem, o mestre pede testes só quando necessário e dá bônus (+2 ou +5) ou sucesso automático para boas ideias e descrições.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Dano mental de medo','op','sah','jogo','Medo','Dano mental de medo',6009,87,'Situações assustadoras causam dano mental (Vontade evita ou reduz). Sempre causa ao menos 1, mesmo com resistência. Inquietante 1d4 (DT 15 anula); perturbadora 1d6 (DT 20 metade); assustadora 2d6 (DT 25 metade); sinistra 4d4 (DT 30 metade); macabra 4d8 (DT 35 metade); aterrorizante 4d12 (DT 40 metade). Ambiente horripilante: 1 por rodada (2 ou 5 em lugares piores). Presença Perturbadora e dano de criaturas de Medo contam como medo.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Efeitos de medo (2d10)','op','sah','jogo','Medo','Efeitos de medo (2d10)',6010,88,'Ao ir a Sanidade 0 por dano mental (ou sofrer dano mental com 0), role 2d10 (+1 por efeito já sofrido na cena; efeito repetido vira o seguinte). Dura até recuperar 1 de Sanidade. 2 Encorajamento (recupera 1 SAN por 5% de NEX e +1d20 num teste); 3 Surto de adrenalina (+5 ataque e dano; fazer outra coisa que não agredir exige Vontade DT 20); 4 Hesitação (atordoado 1 rodada); 5 Fraqueza (fraco); 6 Lapso (frustrado); 7 Ansiedade (falha no próximo teste); 8 Desorientação (desprevenido); 9 Desespero (falha em Vontade); 10 Histeria (–1d20 em tudo por 1d4 rodadas); 11 Abalo (abalado); 12 Alucinação (maior d20 ímpar = falha); 13 Susto (apavorado); 14 Confusão (confuso); 15 Paralisia (paralisado 1d4 rodadas, depois abalado); 16 Pavor (foge; concentração 50% de falha); 17 Desmaio (inconsciente); 18 Trauma (paralisado e 1d6: 1-5 perde 1 ponto permanente de atributo); 19 Loucura (enlouquecendo); 20+ Choque sistêmico (morrendo). Substitui Insanidade e Loucura em campanhas de horror.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Acalmar (medo)','op','sah','jogo','Medo','Acalmar (medo)',6011,88,'Treinado em Diplomacia, Profissão (psicólogo) ou Religião: ação padrão para acalmar alguém adjacente com Sanidade 0; ele recupera 1. DT +5 a cada vez na mesma cena.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Se entregar para o medo','op','sah','jogo','Medo','Se entregar para o medo',6012,88,'Com Sanidade 0, pode rolar um segundo efeito de medo com +5 e interpretar os dois de forma exagerada; na rodada seguinte recupera 1d4 de Sanidade por nível e sai de paralisado ou inconsciente. Uma vez por sessão.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Perseguições','op','sah','jogo','Perseguição','Perseguições',6013,90,'Caçadores e presas fazem teste estendido de Atletismo: 3 sucessos antes de 3 falhas. Caçador que vence alcança a presa; presa que vence escapa. DT: pessoas comuns 15, velozes ou animais 20, criaturas velozes 25+. Outras perícias podem substituir Atletismo se justificadas (cada uma só uma vez por perseguição). De veículo: Pilotagem (ou Adestramento).','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Ações de perseguição','op','sah','jogo','Perseguição','Ações de perseguição',6014,90,'Cortar caminho: –2d20 no teste, mas sucesso vale 2. Esforço extra: +1d20, perde 1d4 PV por vez que já usou na cena. Criar obstáculo (presa): –1d20 no Atletismo e Força DT 15; passou, DT –5 na rodada para todos (um por rodada). Despistar (presa com 1 sucesso): troca Atletismo por Furtividade; passou = 2 sucessos, falhou = 2 falhas. Sacrifício: falha automática, mas +1d20 nos testes dos outros. Atrapalhar (presa): –1d20 no Atletismo e Luta contra Luta ou Reflexos de outra presa; vencendo, ela sofre –2d20.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Opções de perseguição','op','sah','jogo','Perseguição','Opções de perseguição',6015,91,'Testes opostos contra os NPCs; perseguições curtas (2 antes de 2) ou longas (5 ou 7 antes de 3). Eventos (d20): 1-8 nada; obstáculos (falhar = –2d20 na rodada): 9-10 entulho (Força DT 15), 11-12 piso escorregadio (Acrobacia DT 20), 13-14 entulho rolando (Reflexos DT 20), 15 multidão (Intimidação DT 20); atalhos (passar = +2d20, tentar e falhar = –2d20): 16-17 caminho bloqueado (Força DT 15), 18 vias labirínticas (Percepção DT 20), 19 porta trancada (Crime DT 25), 20 caminho na vegetação (Sobrevivência DT 20).','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Visibilidade','op','sah','jogo','Furtividade','Visibilidade',6016,92,'Cada um começa em 0. Terminou a rodada com 3 ou mais, é visto pelo algoz. Opção de grupo: soma das visibilidades; com 5 ou mais, todos com 1+ são vistos. Ação comum (falar normal, andar, investigar): +1. Ação discreta (metade do deslocamento, –1d20 nos testes): +0. Ação chamativa (correr, gritar, atacar, conjurar): +2.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Ações de furtividade','op','sah','jogo','Furtividade','Ações de furtividade',6017,93,'Esconder-se: Furtividade DT 15 (boa ideia +1d20), passou = visibilidade –1. Distrair: Enganação DT 15, passou = –1 para você ou aliado próximo, falhou = +1; um por rodada e DT +5 a cada uso na cena. Chamar atenção: você +2 e um aliado próximo –1. O mestre pode subir as DTs contra algozes mais atentos.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Eventos de furtividade (d20)','op','sah','jogo','Furtividade','Eventos de furtividade (d20)',6018,93,'No início de cada rodada: 1-2 o algoz chega muito perto de alguém, que fica imóvel e sofre 1d6 mental (ou metade da Presença Perturbadora); 3-5 todos +2; 6-8 um personagem +2; 9-15 todos +1; 16-17 um personagem +1; 18-19 nada; 20 um personagem –1.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Fabricação em campo','op','sah','jogo','Fabricação e vida fora da Ordem','Fabricação em campo',6019,94,'Treinado na Profissão certa (armeiro: armas, munições, proteções; químico: explosivos, munições, consumíveis; engenheiro: demais equipamentos) fabrica com ações de interlúdio de manutenção: 1 para consumíveis, 2 (não seguidas) para armas, proteções e equipamentos gerais. Modificados e paranormais não. DT por categoria: 0 15, I 20, II 25, III 30, IV 35; sem kit, –5. Item improvisado: DT –5, dura uma cena. Precisa de matéria-prima.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Folgas da Ordem','op','sah','jogo','Fabricação e vida fora da Ordem','Folgas da Ordem',6020,94,'Entre missões, o mestre pode dar uma folga (mais se passar muito tempo; cerca de uma a cada três meses). Em cada folga, cada personagem cuida de um interesse pessoal.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Interesses pessoais','op','sah','jogo','Fabricação e vida fora da Ordem','Interesses pessoais',6021,95,'Relacionamento: duas perícias (DT 20); 2 sucessos = 1d6 de bônus para a próxima missão (20 natural: 3d6); 0 sucessos = sem relaxar até resolver numa ação de interlúdio. Trabalho: dois testes de Profissão (DT 20); 2 sucessos = item extra de categoria I (20 natural: II); 0 = problema que pode exigir ações de interlúdio (1 em 1d4) ou faz perder o interesse. Lazer: dois testes (DT 20); 2 sucessos = +2 PE máximos na próxima missão (20 natural: +5); 0 = PE máximos reduzidos pelo limite de PE na próxima sessão. Agente atencioso: cada ação de interlúdio gasta na missão com o interesse dá +2 cumulativo na próxima folga.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Busca pessoal','op','sah','jogo','Fabricação e vida fora da Ordem','Busca pessoal',6022,97,'Objetivo longo combinado com o mestre (3 ou 4 pistas). Em cada folga: uma perícia do jogador e uma do mestre (DT 25); 2 sucessos = uma pista (20 natural: +1d20 em Vontade na próxima missão); 0 = frustrado até gastar duas ações de interlúdio. A conclusão acontece em jogo; recompensa equivalente a um poder de classe.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Munição das armas novas','op','sah','jogo','Equipamento','Munição das armas novas',6023,38,'Com a contagem de munição (OPRPG p.174): espingarda de cano duplo 2 balas, pistola pesada 10, revólver compacto 5. Carregador Rápido (modificação para armas de fogo, bestas e balestras): arma de fogo recarrega com ação livre uma vez por rodada; besta ou balestra faz até cinco recargas livres com uma mão, depois um virote por ação de movimento.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Duração de baterias (opção)','op','sah','jogo','Equipamento','Duração de baterias (opção)',6024,39,'Na primeira vez por cena que usa o aparelho, rola 1d12; a cada nova cena o dado cai um passo (d10, d8... até d4). Tirou 1, a bateria acabou. Recarregar volta ao d12. Com Bateria Potente, o dado cai um passo a cada dois usos.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Limite de itens vestidos (opção)','op','sah','jogo','Equipamento','Limite de itens vestidos (opção)',6025,43,'No máximo quatro itens vestidos com benefício (proteções, vestimentas, bandoleiras...). O quinto não funciona até tirar outro. Vestir ou despir é ação de movimento (guardar é outra de movimento; largar é livre). Roupas comuns não contam.','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Invisibilidade','op','sah','jogo','Ameaças','Invisibilidade',6026,125,'Ser invisível tem camuflagem total, +15 em Furtividade contra ouvir e quem não o vê fica desprevenido contra ele. Recebe +2d20 nos ataques contra quem não está cego (alvos cegos sofrem –5 na Defesa).','{"comp": "sah"}'::jsonb),
('op:sah:jogo:Recarga','op','sah','jogo','Ameaças','Recarga',6027,125,'Habilidade com recarga só pode ser usada de novo depois de gastar a ação indicada ou cumprir a condição.','{"comp": "sah"}'::jsonb),
('op:sah:opcional:Nível de experiência','op','sah','opcional','NEX e experiência','Nível de experiência',6028,98,'O NEX passa a medir só a exposição ao Outro Lado; a competência vira nível de experiência (1 nível = 5% de NEX) para PV, PE, SAN, pré-requisitos de classe (menos poderes paranormais) e efeitos de origem e habilidade. Começa no nível 1 e sobe ao concluir missões. O NEX segue valendo para afinidade, poderes paranormais e imunidade à Presença Perturbadora. Transcender deixa de ser poder de classe: ao atingir um NEX com alteração, faz o ritual de conexão e ganha o poder.','{"comp": "sah"}'::jsonb),
('op:sah:opcional:Ganhando NEX','op','sah','opcional','NEX e experiência','Ganhando NEX',6029,98,'Começa em 0%. Exposição branda (ler sobre o Outro Lado): nada. Moderada (manusear origem paranormal, local com Membrana danificada): +1%. Profunda (contato com criatura até VD 300): +2%. Total (Membrana arruinada, criatura acima de VD 300): +5%. Aprender ritual: + o círculo. Exposições repetidas podem dar menos. Máximo 99% sem desconjuração.','{"comp": "sah"}'::jsonb),
('op:sah:opcional:Progressão de NEX (gerais)','op','sah','opcional','NEX e experiência','Progressão de NEX (gerais)',6030,99,'NEX 25%: Ocultismo sem treino (treinado: +2), mas –5 em Diplomacia, Enganação ou Intimidação. NEX 35%: soma um atributo (não Presença) no total de PE, mas –5 em Atletismo, Fortitude ou Reflexos. NEX 50%: no próximo Transcender ganha afinidade com Conhecimento, Energia, Morte ou Sangue e passa a sofrer as alterações dele, com marcas visuais.','{"comp": "sah"}'::jsonb),
('op:sah:opcional:Alterações de Sangue','op','sah','opcional','NEX e experiência','Alterações de Sangue',6031,100,'NEX 60%: +1d20 em Sobrevivência e imune a calor e frio extremos, mas não pode escolher 10. NEX 75%: conjura Aprimorar Físico só em si (se conhece, –1 PE em si), –1d20 em Ciências, Medicina e Tecnologia. NEX 90%: penalidade vira –2d20; conjura Forma Monstruosa (se conhece, –1 PE) e +2 PE nela anula as penalidades durante o efeito.','{"comp": "sah"}'::jsonb),
('op:sah:opcional:Alterações de Morte','op','sah','opcional','NEX e experiência','Alterações de Morte',6032,100,'NEX 60%: +1d20 em Iniciativa e Reflexos, –1d20 em Diplomacia e Intuição. NEX 75%: conjura Velocidade Mortal (se conhece, –1 PE), penalidade vira –2d20 e vale também para Enganação e Intimidação. NEX 90%: não pode ser surpreendido e, em cenas por rodadas, pode esperar quem tem Iniciativa menor declarar e testar antes de você; mas perde 3 PE na primeira interação social com cada pessoa na cena.','{"comp": "sah"}'::jsonb),
('op:sah:opcional:Alterações de Conhecimento','op','sah','opcional','NEX e experiência','Alterações de Conhecimento',6033,101,'NEX 60%: vê auras como Terceiro Olho básico permanente (se conhece, –1 PE), mas fica ofuscado para sempre. NEX 75%: Detecção de Ameaças básica permanente (se conhece, –1 PE) e o ofuscado vira –2d20. NEX 90%: fora da escuridão fica cego em vez de ofuscado; conjura Vidência sem superfície refletora (se conhece, –1 PE).','{"comp": "sah"}'::jsonb),
('op:sah:opcional:Alterações de Energia','op','sah','opcional','NEX e experiência','Alterações de Energia',6034,102,'NEX 60%: conjura Coincidência Forçada (se conhece, –1 PE); no início de cada cena role 1d6: 1 ruído (–1d20 em Presença e perícias dela, menos Vontade; –2d20 em 75%, –3d20 em 90%); 2 o mestre disputa par ou ímpar e pode trocar o alvo de uma ação (2 vezes em 75%, 3 em 90%); 3 um tique a fazer ao descrever ações, ou perde 1 de Sanidade (2 em 75%, 3 em 90%); 4 confuso 1 rodada (2 em 75%, 3 em 90%); 5 o mestre anota um resultado de d20 e, quando sair nos seus testes, você e quem está em alcance curto sofrem 1d6 de Energia (2 números em 75%, 3 em 90%); 6 nada. NEX 75%: conjura Tela de Ruído (se conhece, –1 PE). NEX 90%: conjura Salto Fantasma (se conhece, –1 PE), não precisa falar para conjurar e, digitando o ritual num aparelho, DT +2.','{"comp": "sah"}'::jsonb),
('op:sah:opcional:Pontos de determinação','op','sah','opcional','Jogando sem Sanidade','Pontos de determinação',6035,104,'PE e Sanidade viram pontos de determinação (PD). Combatente 6 + Pre (+3 + Pre por NEX); especialista 8 + Pre (+4 + Pre); ocultista 10 + Pre (+5 + Pre); sobrevivente 4 + Pre (+2 por estágio). Custos e dano mental saem dos PD. Cicatrizes Psicológicas vira +1d20 em Vontade contra medo. Dormir recupera só PV; relaxar recupera PD; prato favorito dá 2 PD temporários. Dano mental de criaturas: cada dado cai um passo e a quantidade cai pela metade (arredonda para cima). Perturbado abaixo da metade dos PD; enlouquecendo com dano maior que os PD atuais. Com as regras de Medo, troque Sanidade por PD e reduza um passo os dados das visões. Falhar no Custo do Paranormal converte a perda em PD. (No site: opção "Regra de Determinação" em Sistema e regras.)','{"comp": "sah"}'::jsonb),
('op:sah:opcional:Ferimentos debilitantes','op','sah','opcional','Ferimentos debilitantes','Ferimentos debilitantes',6036,105,'Falhando em Fortitude contra dano massivo, em vez de ir a 0 PV sofre um ferimento (1d6: 1 Agi, 2 For, 3 Int, 4 Pre, 5 Vig, 6 superficial): –1d20 em testes do atributo; em Vigor, –1 PV máximo por 5% de NEX. Acumulam. Curar: alguém treinado em Medicina gasta ação de interlúdio e passa em DT 20; cura um ferimento na próxima ação de dormir.','{"comp": "sah"}'::jsonb),
('op:sah:opcional:Teatro da mente','op','sah','opcional','Jogando sem mapa','Teatro da mente',6037,106,'Sem mapa: descreva usando todos os sentidos, referências conhecidas e ações detalhadas. Distâncias: toque (adjacente), próxima (até 6m, uma ação de movimento), curta (7-9m), média (10-18m, ação completa), considerável (19-36m), longa (37-90m), longínqua (91-150m). Cada ação de movimento avança uma zona; correr com teste DT 25 avança três.','{"comp": "sah"}'::jsonb),
('op:sah:opcional:Patentes','op','sah','opcional','Evolução por patentes','Patentes',6038,108,'Em vez de NEX, a patente mede experiência; usa pontos de determinação. Recruta 0 PP (limite de PD 1, recuperação 1); operador 20 (3, 2); agente especial 50 (6, 3); oficial de operações 100 (10, 4); agente de elite 200 (15, 5). Dormir ou relaxar recupera 1 PV ou PD por patente. Para pré-requisitos, nível = limite de PD. Pontos por missão: solução +10, pista adicional +2 (até 3), morte de inocente –2, morte de membro do grupo –5 (não rebaixa). Deixa os personagens bem mais fracos e mortais.','{"comp": "sah"}'::jsonb),
('op:sah:opcional:Classes por patente','op','sah','opcional','Evolução por patentes','Classes por patente',6039,110,'Combatente: PV 20 + Vig (+10 + Vig por patente), PD 8 + Pre (+4 + Pre), Luta ou Pontaria, Fortitude ou Reflexos e 1 + Int perícias, armas simples e táticas e proteções leves; Ataque Especial 1 PD +5, até 4 PD +20 em elite. Especialista: PV 16 + Vig (+8 + Vig), PD 12 + Pre (+6 + Pre), 7 + Int perícias, armas simples e proteções leves; Eclético (2 PD) e Perito 1 PD +1d6 até 4 PD +1d12. Ocultista: PV 12 + Vig (+6 + Vig), PD 16 + Pre (+8 + Pre), Ocultismo ou Vontade e 3 + Int perícias, armas simples; Escolhido pelo Outro Lado (1º círculo, 2º em agente especial, 3º oficial, 4º elite; 2 rituais por patente). Todos: aumento de atributo em operador e oficial (máx. 4), poder de classe a cada patente a partir de operador, grau de treinamento em agente especial e elite (2/5/3 + Int), trilha em agente especial (1ª), oficial (2ª) e elite (3ª ou 4ª).','{"comp": "sah"}'::jsonb),
('op:sah:opcional:Aprendizado lento','op','sah','opcional','Limites da compreensão humana','Aprendizado lento',6040,113,'O ocultista começa com 3 rituais de 1º círculo e aprende um novo só em NEX ímpar (15%, 25%, 35%...) ou nível ímpar.','{"comp": "sah"}'::jsonb),
('op:sah:opcional:Aprendizado em campo','op','sah','opcional','Limites da compreensão humana','Aprendizado em campo',6041,113,'O ocultista só tem os 3 rituais iniciais; novos rituais são achados em missões e estudados: ação de interlúdio e Ocultismo DT 20 (1º círculo), 25 (2º), 30 (3º) ou 35 (4º); falhou, pode tentar de novo noutra ação. Estudar um selo paranormal também ensina, mas destrói o selo. Só círculos a que tem acesso.','{"comp": "sah"}'::jsonb),
('op:sah:opcional:Conjuração em três rodadas','op','sah','opcional','Conjuração complexa','Conjuração em três rodadas',6042,114,'Ritual leva 3 rodadas seguidas (ações extras dão +2 no teste cada); desprevenido e precisa manter concentração (Vontade ao sofrer dano ou com condição ruim). 1ª etapa, símbolo: desenhado com material de elemento dá –1d20 no teste e um efeito (Sangue: cura 2d6 PV, +1 dado de dano de Sangue ou sangrando; Morte com cinzas: DT +2, +1 dado de Morte ou –2 em testes; Conhecimento com tinta dourada: limite de PE +2, +1 dado de Conhecimento ou ignora um requisito de aprimoramento; Energia com luz: ação de movimento extra, +1 dado de Energia ou ofuscado). 2ª, componentes: consumi-los dá +1d20 (ou use catalisador); com afinidade ou ritual de Medo não precisa. 3ª, invocar: decide custos e alvos e faz Ocultismo DT 20 + custo; falhou, paga tudo e não funciona (e o resultado define o Custo do Paranormal). Extrapolar: soma Presença no limite de PE e usa aprimoramentos como se tivesse um círculo a mais.','{"comp": "sah"}'::jsonb),
('op:sah:opcional:Poderes de ocultista na conjuração complexa','op','sah','opcional','Conjuração complexa','Poderes de ocultista na conjuração complexa',6043,117,'Acelerar Ritual: 4 PE tira 1 rodada. Anular Ritual vira Mesclar Elemento (adiciona efeito de um segundo elemento na 1ª etapa). Camuflar Ocultismo não tem efeito. Conjuração Marcial: armazena um ritual de ação padrão ou menos numa arma e solta com ação livre ao acertar corpo a corpo. Tatuagem Ritualística: o ritual tatuado custa –1 PE e pode pular a 1ª etapa (sem efeito de elemento). Preparar ritual de reação: faz as etapas antes e solta com reação depois; os PE só voltam após soltar.','{"comp": "sah"}'::jsonb),
('op:sah:opcional:Conjurar ritual desconhecido','op','sah','opcional','Rituais desconhecidos','Conjurar ritual desconhecido',6044,117,'Treinado em Ocultismo e com informação suficiente sobre o ritual, qualquer um tenta pela conjuração complexa com DT +5. Falhando, além do normal sofre um desastre paranormal.','{"comp": "sah"}'::jsonb),
('op:sah:opcional:Desastres paranormais (1d8)','op','sah','opcional','Rituais desconhecidos','Desastres paranormais (1d8)',6045,118,'1 Consumido: vira criatura do elemento com VD ~4 x NEX, controlada pelo mestre. 2 Surto elemental: você e todos a 9m sofrem 3d12 por círculo do tipo do elemento (outros: Reflexos DT do ritual +5 metade). 3 Assalto psíquico: 2d10 mental por círculo. 4 Decrepitude motora: –1 Agilidade permanente e desprevenido na cena. 5 Definhamento: –1 Força permanente e debilitado na cena. 6 Oblívio: –1 Intelecto permanente e esmorecido na cena. 7 Eu perdido: –1 Presença permanente e alquebrado na cena. 8 Dor profunda: –1 Vigor permanente e enjoado na cena.','{"comp": "sah"}'::jsonb),
('op:sah:opcional:Combate narrativo','op','sah','opcional','Combate narrativo','Combate narrativo',6046,119,'Sem mapa (toque, curta, média, longa; um turno muda de categoria; fugir é teste oposto). Iniciativa fixa = bônus + 3 por d20 (empate: personagem antes da criatura). Dano médio fixo (média baixa por dado; crítico x2 = máximo, x3 = 1,5 x máximo). Uma ação por turno descrita livremente: simples (sem teste ou sem penalidade), complexa (duas ações, –1d20), extrema (três, –2d20). Coreografia de luta: dois golpes = –1d20 e dano dobrado; três = –2d20 e dano triplicado (ou troque dano extra por manobra). Habilidades que dão bônus custam +1 PE em ação complexa e +2 em extrema; ataques extras não somam com coreografia; só um ritual por turno.','{"comp": "sah"}'::jsonb)
